<?php $food=$data['food']; ?>
<div class="page-actions"><?php badge($food['status']); ?><?php if ((int)$food['donor_id']===(int)$user['id'] && in_array($food['status'],['available','review','rejected'],true)): ?><a class="button small" href="/donations/<?= e($food['id']) ?>/edit">Edit listing</a><form data-api="/api/donations/<?= e($food['id']) ?>/withdraw" data-confirm="Withdraw this unclaimed listing?"><?php formend('Withdraw'); ?><?php endif ?><?php if ((int)$food['donor_id']===(int)$user['id'] && in_array($food['status'],['failed','cancelled'],true)): ?><form data-api="/api/donations/<?= e($food['id']) ?>/relist"><?php formend('Re-screen and relist'); ?><?php endif ?></div>
<div class="dashboard-grid"><article class="panel"><h2><?= e($food['name']) ?></h2><p><?= e($food['description']) ?></p><dl><dt>Offered</dt><dd><?= e($food['quantity']) ?> <?= e($food['unit']) ?> (<?= e($food['quantity_kg']) ?> kg)</dd><dt>Organization</dt><dd><?= e($food['organization_name']) ?></dd><dt>Category</dt><dd><?= e($food['category_name']) ?></dd><dt>Storage</dt><dd><?= e($food['storage_method']) ?> · <?= $food['temperature_c']!==null ? e($food['temperature_c']) . ' °C' : 'Temperature not recorded' ?></dd><dt>Packaging</dt><dd><?= e($food['packaging']) ?></dd><dt>Ingredients</dt><dd><?= e($food['ingredients']) ?></dd><dt>Allergens</dt><dd><?= e($food['allergens']) ?></dd><dt>Prepared</dt><dd><?php stamp($food['prepared_at']); ?></dd><dt>Use by</dt><dd><?php stamp($food['use_by']); ?></dd><dt>Pickup by</dt><dd><?php stamp($food['deadline']); ?></dd></dl></article><article class="panel"><h2>Collection location</h2><p><?= e($food['address']) ?></p><div class="map" data-lat="<?= e($food['latitude']) ?>" data-lng="<?= e($food['longitude']) ?>" aria-label="Pickup location"></div><a class="underlined" href="https://www.openstreetmap.org/?mlat=<?= e($food['latitude']) ?>&mlon=<?= e($food['longitude']) ?>#map=16/<?= e($food['latitude']) ?>/<?= e($food['longitude']) ?>" target="_blank" rel="noopener">Open map ↗</a></article></div>
<article class="panel spaced"><h2>Food photographs</h2><div class="food-images"><?php foreach ($data['images'] as $image): ?><img src="/files/donation/<?= e($image['id']) ?>" alt="Photograph of <?= e($food['name']) ?>" loading="lazy"><?php endforeach ?></div><?php if (!$data['images']): ?><p>No photographs uploaded.</p><?php endif ?>
<?php if ((int)$food['donor_id']===(int)$user['id']): ?><form data-api="/api/uploads" enctype="multipart/form-data"><input type="hidden" name="kind" value="donation"><input type="hidden" name="id" value="<?= e($food['id']) ?>"><?php field('file','Add a photograph (up to 5 MB)','file','','required accept="image/jpeg,image/png,image/webp"');formend('Upload photograph'); ?><?php endif ?></article>
<article class="panel spaced"><h2>Safety screening & traceability</h2><p>Screening records handling declarations and configured eligibility rules. It is not food-safety certification. Images and matching scores do not establish food safety.</p><?php foreach ($data['safety'] as $record): ?><details <?= $record===$data['safety'][0] ? 'open' : '' ?>><summary><?= e($record['outcome']) ?> · <?= e($record['version']) ?> · <?php stamp($record['created_at']); ?></summary><?php $reasons=json_decode($record['reasons'],true); ?><p><?= e($reasons ? implode(' ',$reasons) : 'Recorded declarations pass the configured screening checks.') ?></p><a class="underlined" href="<?= e($record['source_url']) ?>" target="_blank" rel="noopener">Rule source ↗</a></details><?php endforeach ?></article>
<article class="panel spaced"><h2>Matching recommendations</h2><?php if (isset($data['matches']['configuration'])): ?><p>Version <?= e($data['matches']['configuration']['version']) ?>. Scores are experimental rankings; feasibility is a heuristic, not a calibrated probability.</p><?php endif ?>
<?php if (!$data['matches']['ranked']): ?><p class="empty-state">No eligible recommendations currently. <?php if ($user['role']==='receiver'): ?><a class="underlined" href="/receiving">Review your capacity, categories and availability.</a><?php endif ?></p><?php endif ?>
<?php foreach ($data['matches']['ranked'] as $match): ?><div class="match-row"><div><h3><?= e($match['name']) ?> · <?= e(number_format($match['score']*100,1)) ?>/100</h3><p><?= e($match['distance_km']) ?> km · <?= e($match['free_capacity_kg']) ?> kg free · <?= e($match['feasibility']['level']) ?> pickup feasibility</p><div class="score-components"><?php foreach ($match['components'] as $component=>$score): ?><span><?= e(ucfirst($component)) ?> <?= e(number_format($score,3)) ?></span><?php endforeach ?></div><p><?= e(implode(' ',$match['explanation'])) ?></p><p class="muted">Estimated travel <?= e($match['feasibility']['travel_minutes']) ?> min + <?= e($match['feasibility']['handling_minutes']) ?> min handling. Estimated arrival <?php stamp($match['feasibility']['estimated_arrival']); ?></p></div>
<?php if ($user['role']==='donor'): ?><form data-api="/api/matching/propose"><input type="hidden" name="match_id" value="<?= e($match['match_id']) ?>"><?php formend('Notify this receiver'); ?><?php endif ?><?php if ($user['role']==='receiver'): ?><form data-api="/api/matching/accept" data-confirm="Accept this full donation and reserve its weight against your capacity?"><input type="hidden" name="donation_id" value="<?= e($food['id']) ?>"><?php formend('Accept and reserve collection'); ?><form data-api="/api/matching/reject"><input type="hidden" name="match_id" value="<?= e($match['match_id']) ?>"><?php formend('Decline recommendation'); ?><?php endif ?></div><?php endforeach ?>
<?php if ($data['matches']['excluded']): ?><details><summary>Why candidates were excluded</summary><?php foreach ($data['matches']['excluded'] as $excluded): ?><p><?= isset($excluded['receiver_id']) ? 'Receiver ' . e($excluded['receiver_id']) . ': ' : '' ?><?= e($excluded['reason']) ?></p><?php endforeach ?></details><?php endif ?></article>
<article class="panel spaced"><h2>Lifecycle history</h2><ul class="activity-list"><?php foreach ($data['events'] as $event): ?><li><span><?= e($event['event']) ?> <?= $event['details']!=='{}' && $event['details']!=='[]' ? e($event['details']) : '' ?></span><?php stamp($event['created_at']); ?></li><?php endforeach ?></ul></article>
<?php if ($data['reviews']): ?><article class="panel spaced"><h2>Collection feedback</h2><?php foreach ($data['reviews'] as $review): ?><p><?= e($review['rating']) ?>/5 — <?= e($review['comment']) ?></p><?php endforeach ?></article><?php endif ?>
